// Keeps a corrupt checkpoint as evidence beside the checkpoint, never overwriting an earlier one.
async function quarantineCheckpoint(checkpointPath) {
  const directory = join(dirname(checkpointPath), 'recovery');
  await mkdir(directory, { recursive: true });
  let target = join(directory, 'checkpoint.bad.json');
  if (await exists(target)) target = join(directory, `checkpoint.bad.${randomUUID()}.json`);
  await rename(checkpointPath, target);
}

async function exists(path) {
  try {
    await stat(path);
    return true;
  } catch (error) {
    if (error.code === 'ENOENT') return false;
    throw error;
  }
}

export async function processBatch({ inputPath, outputPath, checkpointPath, batchSize = 4 }) {
  if (!Number.isSafeInteger(batchSize) || batchSize <= 0) {
    throw new RangeError('batchSize must be a positive safe integer');
  }
  let nextLine = 0;
  let checkpointText;
  try {
    checkpointText = await readFile(checkpointPath, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (checkpointText !== undefined) {
    let parsed;
    try {
      parsed = JSON.parse(checkpointText).nextLine;
    } catch {
      parsed = undefined;
    }
    if (Number.isSafeInteger(parsed) && parsed >= 0) {
      nextLine = parsed;
    } else {
      // Corrupt checkpoint: keep it as evidence and replay from the start.
